package com.example.smartexpenseanalyzer.service;
import com.example.smartexpenseanalyzer.model.*; import org.springframework.stereotype.Service; import java.util.*; import java.math.*; import java.util.stream.*; import com.example.smartexpenseanalyzer.util.MoneyUtils;
@Service public class DashboardService { public Map<String,Object> summarize(AppUser u,List<Expense> all){BigDecimal total=MoneyUtils.total(all);Map<String,BigDecimal> cats=all.stream().collect(Collectors.groupingBy(e->e.category,Collectors.reducing(BigDecimal.ZERO,e->e.amount,BigDecimal::add)));Map<String,BigDecimal> months=all.stream().collect(Collectors.groupingBy(e->e.date.toString().substring(0,7),TreeMap::new,Collectors.reducing(BigDecimal.ZERO,e->e.amount,BigDecimal::add)));BigDecimal highest=MoneyUtils.highest(all);Map<String,Object> out=new LinkedHashMap<>();out.put("total",total);out.put("travel",cats.getOrDefault("Travel",BigDecimal.ZERO));out.put("food",cats.getOrDefault("Food",BigDecimal.ZERO));out.put("shoppingGifts",cats.getOrDefault("Shopping",BigDecimal.ZERO).add(cats.getOrDefault("Gifts",BigDecimal.ZERO)));out.put("accommodation",cats.getOrDefault("Accommodation",BigDecimal.ZERO));out.put("highest",highest);out.put("budget",u.budget);out.put("remaining",MoneyUtils.remaining(u.budget,total));out.put("count",all.size());out.put("categories",cats);out.put("months",months);out.put("recent",all.stream().limit(5).map(e->Map.<String,Object>of("id",e.id,"category",e.category,"description",e.description,"amount",e.amount,"date",e.date,"tripId",e.trip==null?0:e.trip.id,"tripName",e.trip==null?"":e.trip.name)).toList());return out;} }
